   !> IEF-PCM (gaussian charges): linear response of the v gradient
   !>
   !> - Directions of v only; the state is not changed
   !> - Needs iefpcm_solve on the same state first; keeps the state as it is
   !> - Arrays carry a last dimension nblk: one direction per column block
   !> - Vectors are (npt, nblk), point fields (3, npt, nblk)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of iefpcm
   !> @param[in] dv  direction for v
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] error  error handling; allocated on failure
   subroutine iefpcm_response(state, dv, hvp_v, error)
      !> State of iefpcm
      type(iefpcm_state), intent(inout) :: state
      !> Direction for v
      real(wp), contiguous, intent(in) :: dv(:, :)
      !> Hessian times direction, v block
      real(wp), contiguous, intent(out) :: hvp_v(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt, nblk, blk

      if (state%matrix_free) then
         call iefpcm_mf_response(state, dv, hvp_v, error)
         return
      end if
      if (state%ready < 3) then
         call fatal_error(error, "[iefpcm_response] call iefpcm_solve first")
         return
      end if
      npt = state%npt
      nblk = size(dv, 2)
      if (any(shape(dv) /= [npt, nblk])) then
         call fatal_error(error, "[iefpcm_response] dv: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt, nblk])) then
         call fatal_error(error, "[iefpcm_response] hvp_v: wrong shape")
         return
      end if
      do blk = 1, nblk
         call iefpcm_response_one(state, dv(:, blk), hvp_v(:, blk), error)
         if (allocated(error)) return
      end do
   end subroutine iefpcm_response

