         call gemv(state%s7, real(state%cx_s14, wp), tmp14)
         call gemv(state%s7, aimag(state%cx_s14), tmp15)
         tmp13 = cmplx(tmp14, tmp15, wp)
         tmp16 = state%a*tmp13
         call gemv(state%s12, real(tmp16, wp), tmp18)
         call gemv(state%s12, aimag(tmp16), tmp19)
         tmp17 = cmplx(tmp18, tmp19, wp)
         tmp20 = state%cx_s8*tmp17
         tmp21 = tmp13 + tmp20
         tmp22 = -tmp21
         tmp23 = tmp5 + tmp22
         tmp24 = sum(tmp10*tmp23)
         energy = energy + tmp24
      end if

      state%cx_ready = 3
   end subroutine iefpcm_complex_solve

