      !> Hessian times direction, F block
      real(wp), contiguous, intent(out) :: hvp_F(:, :)
      !> Hessian times direction, a block
      real(wp), contiguous, intent(out) :: hvp_a(:, :)
      !> Hessian times direction, v block
      real(wp), contiguous, intent(out) :: hvp_v(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt, nblk, blk

      if (state%ready < 4) then
         call fatal_error(error, "[iefpcm_mf_tangent] call iefpcm_weights first")
         return
      end if
      npt = state%npt
      nblk = size(dr, 3)
      if (any(shape(dr) /= [3, npt, nblk])) then
         call fatal_error(error, "[iefpcm_mf_tangent] dr: wrong shape")
         return
      end if
      if (any(shape(dn) /= [3, npt, nblk])) then
         call fatal_error(error, "[iefpcm_mf_tangent] dn: wrong shape")
         return
      end if
      if (any(shape(dk1) /= [npt, nblk])) then
         call fatal_error(error, "[iefpcm_mf_tangent] dk1: wrong shape")
         return
      end if
      if (any(shape(dk2) /= [npt, nblk])) then
         call fatal_error(error, "[iefpcm_mf_tangent] dk2: wrong shape")
         return
      end if
      if (any(shape(dxi) /= [npt, nblk])) then
