   !> IEF-PCM (gaussian charges): gradient tangents along blocks of directions
   !>
   !> - Directions of the cavity and QM inputs; for the inputs of the last solve
   !> - Needs iefpcm_complex_weights on the same state first; keeps the state as it is
   !> - Arrays carry a last dimension nblk: one direction per column block
   !> - Vectors are (npt, nblk), point fields (3, npt, nblk)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of iefpcm
   !> @param[in] dr  direction for r
   !> @param[in] dn  direction for n
   !> @param[in] dk1  direction for k1
   !> @param[in] dk2  direction for k2
   !> @param[in] dxi  direction for xi
   !> @param[in] dF  direction for F
   !> @param[in] da  direction for a
   !> @param[in] dv  direction for v
   !> @param[out] hvp_r  hessian times direction, r block
   !> @param[out] hvp_n  hessian times direction, n block
   !> @param[out] hvp_k1  hessian times direction, k1 block
   !> @param[out] hvp_k2  hessian times direction, k2 block
   !> @param[out] hvp_xi  hessian times direction, xi block
   !> @param[out] hvp_F  hessian times direction, F block
   !> @param[out] hvp_a  hessian times direction, a block
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] error  error handling; allocated on failure
   subroutine iefpcm_complex_mf_tangent(state, dr, dn, dk1, dk2, dxi, dF, da, dv, hvp_r, hvp_n, &
                                        hvp_k1, hvp_k2, hvp_xi, hvp_F, hvp_a, hvp_v, error)
      !> State of iefpcm
      type(iefpcm_complex_state), intent(inout) :: state
      !> Direction for r
      real(wp), contiguous, intent(in) :: dr(:, :, :)
      !> Direction for n
      real(wp), contiguous, intent(in) :: dn(:, :, :)
      !> Direction for k1
      real(wp), contiguous, intent(in) :: dk1(:, :)
      !> Direction for k2
      real(wp), contiguous, intent(in) :: dk2(:, :)
      !> Direction for xi
      real(wp), contiguous, intent(in) :: dxi(:, :)
      !> Direction for F
      real(wp), contiguous, intent(in) :: dF(:, :)
      !> Direction for a
      real(wp), contiguous, intent(in) :: da(:, :)
      !> Direction for v
      complex(wp), contiguous, intent(in) :: dv(:, :)
      !> Hessian times direction, r block
      complex(wp), contiguous, intent(out) :: hvp_r(:, :, :)
      !> Hessian times direction, n block
      complex(wp), contiguous, intent(out) :: hvp_n(:, :, :)
      !> Hessian times direction, k1 block
      complex(wp), contiguous, intent(out) :: hvp_k1(:, :)
      !> Hessian times direction, k2 block
      complex(wp), contiguous, intent(out) :: hvp_k2(:, :)
      !> Hessian times direction, xi block
      complex(wp), contiguous, intent(out) :: hvp_xi(:, :)
      !> Hessian times direction, F block
      complex(wp), contiguous, intent(out) :: hvp_F(:, :)
      !> Hessian times direction, a block
      complex(wp), contiguous, intent(out) :: hvp_a(:, :)
      !> Hessian times direction, v block
      complex(wp), contiguous, intent(out) :: hvp_v(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt, nblk, blk

      if (state%cx_ready < 4 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, "[iefpcm_complex_mf_tangent] call iefpcm_complex_weights first")
         return
      end if
      npt = state%npt
      nblk = size(dr, 3)
      if (any(shape(dr) /= [3, npt, nblk])) then
         call fatal_error(error, "[iefpcm_complex_mf_tangent] dr: wrong shape")
         return
      end if
      if (any(shape(dn) /= [3, npt, nblk])) then
         call fatal_error(error, "[iefpcm_complex_mf_tangent] dn: wrong shape")
         return
      end if
      if (any(shape(dk1) /= [npt, nblk])) then
         call fatal_error(error, "[iefpcm_complex_mf_tangent] dk1: wrong shape")
         return
      end if
      if (any(shape(dk2) /= [npt, nblk])) then
         call fatal_error(error, "[iefpcm_complex_mf_tangent] dk2: wrong shape")
         return
      end if
      if (any(shape(dxi) /= [npt, nblk])) then
         call fatal_error(error, "[iefpcm_complex_mf_tangent] dxi: wrong shape")
         return
      end if
      if (any(shape(dF) /= [npt, nblk])) then
         call fatal_error(error, "[iefpcm_complex_mf_tangent] dF: wrong shape")
         return
      end if
      if (any(shape(da) /= [npt, nblk])) then
         call fatal_error(error, "[iefpcm_complex_mf_tangent] da: wrong shape")
         return
      end if
      if (any(shape(dv) /= [npt, nblk])) then
         call fatal_error(error, "[iefpcm_complex_mf_tangent] dv: wrong shape")
         return
      end if
      if (any(shape(hvp_r) /= [3, npt, nblk])) then
         call fatal_error(error, "[iefpcm_complex_mf_tangent] hvp_r: wrong shape")
         return
      end if
      if (any(shape(hvp_n) /= [3, npt, nblk])) then
         call fatal_error(error, "[iefpcm_complex_mf_tangent] hvp_n: wrong shape")
         return
      end if
      if (any(shape(hvp_k1) /= [npt, nblk])) then
         call fatal_error(error, "[iefpcm_complex_mf_tangent] hvp_k1: wrong shape")
         return
      end if
      if (any(shape(hvp_k2) /= [npt, nblk])) then
         call fatal_error(error, "[iefpcm_complex_mf_tangent] hvp_k2: wrong shape")
         return
      end if
      if (any(shape(hvp_xi) /= [npt, nblk])) then
         call fatal_error(error, "[iefpcm_complex_mf_tangent] hvp_xi: wrong shape")
         return
      end if
      if (any(shape(hvp_F) /= [npt, nblk])) then
         call fatal_error(error, "[iefpcm_complex_mf_tangent] hvp_F: wrong shape")
         return
      end if
      if (any(shape(hvp_a) /= [npt, nblk])) then
         call fatal_error(error, "[iefpcm_complex_mf_tangent] hvp_a: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt, nblk])) then
         call fatal_error(error, "[iefpcm_complex_mf_tangent] hvp_v: wrong shape")
         return
      end if
      do blk = 1, nblk
         call iefpcm_complex_mf_tangent_one(state, dr(:, :, blk), dn(:, :, blk), dk1(:, blk), &
                                            dk2(:, blk), dxi(:, blk), dF(:, blk), da(:, blk), &
                                            dv(:, blk), hvp_r(:, :, blk), hvp_n(:, :, blk), &
                                            hvp_k1(:, blk), hvp_k2(:, blk), hvp_xi(:, blk), &
                                            hvp_F(:, blk), hvp_a(:, blk), hvp_v(:, blk), error)
         if (allocated(error)) return
      end do
   end subroutine iefpcm_complex_mf_tangent

   !> One direction of iefpcm_complex_mf_tangent
   !>
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of iefpcm
   !> @param[in] dr  direction for r
   !> @param[in] dn  direction for n
