   !> Apply operator 1 or its transpose
   !>
   !> @param[in]  self   operator
   !> @param[in]  trans  apply the transpose if true
   !> @param[in]  x      input vector
   !> @param[out] y      result vector
   subroutine iefpcm_op1_apply(self, trans, x, y)
      !> Operator
      class(iefpcm_op1), intent(in) :: self
      !> Apply the transpose
      logical, intent(in) :: trans
      !> Input vector
      real(wp), contiguous, intent(in) :: x(:)
      !> Result vector
      real(wp), contiguous, intent(out) :: y(:)

      if (trans) then
         block
            real(wp) :: tmp1(self%npt), tmp2(self%npt), tmp3(self%npt), tmp4(self%npt)

            call gemv(self%c3, x, tmp1, trans="t")
            tmp2 = self%a*tmp1
            tmp3 = self%c2*tmp2
            tmp4 = x + tmp3
            call gemv(self%c1, tmp4, y, trans="t")
         end block
      else
         block
            real(wp) :: tmp1(self%npt), tmp2(self%npt), tmp3(self%npt), tmp4(self%npt)

            call gemv(self%c1, x, tmp1)
            tmp2 = self%a*tmp1
            call gemv(self%c3, tmp2, tmp3)
            tmp4 = self%c2*tmp3
            y = tmp1 + tmp4
         end block
      end if
   end subroutine iefpcm_op1_apply

   !> Form operator 1 as a dense matrix
   !>
   !> @param[in]  self  operator
   !> @param[out] a     matrix of shape (npt, npt)
   !> @param[out] error  error handling; allocated if workspace allocation failed
   subroutine iefpcm_op1_assemble(self, a, error)
      !> Operator
      class(iefpcm_op1), intent(in) :: self
      !> Dense operator matrix
      real(wp), contiguous, intent(out) :: a(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: stat
      real(wp), allocatable :: tmp1(:, :), tmp2(:, :), tmp3(:, :)
      integer :: i

      allocate (tmp1(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp2(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp3(self%npt, self%npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[iefpcm_op1_assemble] allocation failed")
         return
      end if
      do i = 1, self%npt
         tmp1(:, i) = self%a(i)*self%c3(:, i)
      end do
      call gemm(tmp1, self%c1, tmp2)
      tmp3 = self%c2*tmp2
      a = self%c1 + tmp3
